          "section": "读文章",
          "raw": "【第1段意群顺译】家庭作业从来都不太受学生甚至许多家长的欢迎，但近年来它尤其受到蔑视。全国各地的学区，最近的洛杉矶联合学区，正在修改他们对这种教育仪式的想法。不幸的是，洛杉矶联合大学制定了一项不灵活的政策，规定除某些高级课程外，家庭作业在学生学业成绩中所占的比例可能不再超过 10%。...",
          "html": "<div class=\"coarseStack\"><div class=\"coarsePara currentFocus\"><p>【第1段意群顺译】家庭作业从来都不太受学生甚至许多家长的欢迎，但近年来它尤其受到蔑视。全国各地的学区，最近的洛杉矶联合学区，正在修改他们对这种教育仪式的想法。不幸的是，洛杉矶联合大学制定了一项不灵活的政策，规定除某些高级课程外，家庭作业在学生学业成绩中所占的比例可能不再超过 10%。...</p></div></div>",
