          "html": "<section class=\"revealPart\" id=\"focus-paragraph-4-0\">\n<h3>完整原文 · 第4段</h3>\n<p>At the same time, the policy addresses none of the truly thorny questions about homework. If the district finds homework to be unimportant to its students’ academic achievement, it should move to reduce or eliminate the assignments, not make them count for almost nothing. Conversely, if homework matters, it should account for a significant portion of the grade. Meanwhile, this policy does nothing to ensure that the homework students receive is meaningful or appropriate to their age and the subject, or that teachers are not assigning more than they are willing to review and correct.</p>\n</section>\n<section class=\"revealPart\" id=\"focus-paragraph-4-1\">\n<h3>意群划分 · 第4段</h3>\n<p>At the same time, / the policy addresses none of the truly thorny questions about homework. / If the district finds homework to be unimportant to its students’ academic achievement, / it should move to reduce or eliminate the assignments, / not make them count for almost nothing. / Conversely, / / if homework matters, / it should account for a significant portion of the grade. / Meanwhile, / this policy does nothing to ensure / that the homework students receive is meaningful or appropriate to their age and the subject, / or / that teachers are not assigning more than they are willing to review and correct.</p>\n</section>\n<section class=\"revealPart\" id=\"focus-paragraph-4-2\">\n<h3>意群翻译 · 第4段</h3>\n<p style=\"line-height:1.8;color:#2563eb;font-weight:500\">同时 / 该政策没有解决有关家庭作业的任何真正棘手的问题<br>如果学区发现家庭作业对其学生的学业成绩并不重要 / 它应该减少或消除任务 / 不让它们变得毫无价值<br>反过来 / 如果家庭作业很重要 / 它应该占成绩的很大一部分<br>同时 / 这项政策无助于确保 / 学生收到的家庭作业有意义或适合他们的年龄和科目 / 或者 / 教师布置的作业不会超出他们愿意审查和纠正的范围</p>\n</section>\n<section class=\"revealPart\" id=\"focus-paragraph-4-3\">\n<h3>标准译文 · 第4段</h3>\n<p>与此同时，该政策没有解决有关家庭作业的任何真正棘手的问题。如果学区发现家庭作业对学生的学业成绩并不重要，就应该减少或取消作业，而不是让它们几乎毫无价值。相反，如果家庭作业很重要，它应该占成绩的很大一部分。与此同时，这项政策并不能确保学生收到的家庭作业有意义或适合他们的年龄和科目，或者教师布置的作业不会超出他们愿意复习和纠正的范围。</p>\n</section>",
