          "section": 2,
          "title": "第5段 · 篇章精读",
          "html": "<section class=\"revealPart\" id=\"focus-paragraph-5-0\">\n<h3>完整原文 · 第5段</h3>\n<p>The homework rules should be put on hold while the school board, which is responsible for setting educational policy, looks into the matter and conducts public hearings. It is not too late for L.A. Unified to do homework right.</p>\n</section>\n<section class=\"revealPart\" id=\"focus-paragraph-5-1\">\n<h3>意群划分 · 第5段</h3>\n<p>The homework rules should be put on hold / while the school board, / / which is responsible for setting educational policy, / looks into the matter and conducts public hearings. / It is not too late for L.A. / Unified to do homework right.</p>\n</section>\n<section class=\"revealPart\" id=\"focus-paragraph-5-2\">\n<h3>意群翻译 · 第5段</h3>\n<p style=\"line-height:1.8;color:#2563eb;font-weight:500\">家庭作业规则应该被搁置 / 而学校董事会 / 负责制定教育政策 / 调查此事并举行公开听证会<br>对于洛杉矶来说还不算太晚<br>统一做作业</p>\n</section>\n<section class=\"revealPart\" id=\"focus-paragraph-5-3\">\n<h3>标准译文 · 第5段</h3>\n<p>在负责制定教育政策的学校董事会调查此事并举行公开听证会期间，家庭作业规则应暂停。对于洛杉矶联合大学来说，做好功课还不算太晚。</p>\n</section>",
