          "html": "<section class=\"revealPart\">\n<h4>句子精析 (4/5)</h4>\n<p style=\"font-family:'Times New Roman',serif;font-size:1.15em;color:#1e293b;line-height:1.7\"><strong>原句：</strong>When nursery colours were introduced, pink was actually considered the more masculine colour, a pastel version of red, which was associated with strength.</p>\n<p><strong>意群断句：</strong><code>When nursery colours were introduced, / pink was actually considered the more masculine colour, / a pastel version of red, / / which was associated with strength.</code></p>\n<p style=\"margin:8px 0\"><strong>【意群翻译】：</strong><span style=\"color:#2563eb;font-weight:500;font-size:1.02em\">当引入幼儿园颜色时 / 粉色实际上被认为是更男性化的颜色 / 柔和的红色 / 这与力量有关</span></p>\n<div style=\"margin:8px 0;background:#f8fafc;border-left:4px solid #0f766e;padding:8px 12px;border-radius:0 6px 6px 0\">\n  <p style=\"font-weight:bold;color:#0f766e;margin-bottom:4px\">【句法拆解与逻辑剖析】</p>\n  <ul style=\"margin:6px 0 0 18px;padding:0;line-height:1.7;color:#334155\"><li style=\"margin-bottom:5px\"><b>时间状语从句</b>：由连词 <code>When</code> 引导从句 <code>When nursery colours were introduced</code>，限定主句论述的时空背景或逻辑前提。</li><li style=\"margin-bottom:5px\"><b>非限制性定语从句</b>：<code>,which was associated with strength....</code> 引导非限制性定语从句，对前文先行词进行补充说明与信息拓展。</li><li style=\"margin-bottom:5px\"><b>同位语/插入语</b>：<code>a pastel version of red</code> 充当同位语/插入语，紧随其后对前置名词提供身份补充或同等指代。</li><li style=\"margin-bottom:5px\"><b>介词短语修饰</b>：<code>with strength....</code> 充当状语或定语，补充方式、伴随或背景条件。</li></ul>\n</div>\n<p style=\"margin-top:8px\"><strong>【满分参考汉译】</strong><span style=\"color:#0f766e;font-weight:600;font-size:1.05em\">当引入童趣色时，粉色实际上被认为是更男性化的颜色，是红色的柔和版本，与力量相关。</span></p>\n</section>",
