          "raw": "On July 29th they were relieved, / at least temporarily. / A federal appeals court overturned the prior decision, / ruling / that Myriad Genetics could indeed hold patents to two genes / that help forecast a woman’s risk of breast cancer. / The chief executive of Myriad, / a company in Utah, / said the ruling was a blessing to firms and patients alike.",
