          "section": "32题",
          "raw": "## 32题\n\n**Those who are against gene patents believe that _____.**\n\n> 那些反对基因专利的人认为_____。\n\n我们先看题干中的核心考查点。根据题文同序原则与刚才粗读文章的逻辑脉络，该题干讨论的内容主要在第 2 段展开，所以我们直接回第 2 段定位精读。\n\n> 原文参考：\n>\n> On July 29th they were relieved, at least temporarily. A federal appeals court overturned the prior decision, ruling that Myriad Genetics could indeed hold patents to two genes that help forecast a woman’s risk of breast cancer. The chief executive of Myriad, a company in Utah, said the ruling was a blessing to firms and patients alike.\n>\n> 开始精读：\n>\n> On July 29th they were relieved, / at least temporarily. / A federal appeals court overturned the prior decision, / ruling / that Myriad Genetics could indeed hold patents to two genes / that help forecast a woman’s risk of breast cancer. / The chief executive of Myriad, / a company in Utah, / said the ruling was a blessing to firms and patients alike.\n>\n> 逐意群顺译：\n>\n> 7 月 29 日，他们松了一口气，至少暂时松了口气。联邦上诉法院推翻了先前的裁决，裁定 Myriad Genetics 确实可以拥有两个有助于预测女性患乳腺癌风险的基因的专利。犹他州 Myriad 公司的首席执行官表示，这一裁决对公司和患者来说都是一件好事。\n>\n> 意群逻辑串联：\n>\n> 核心主体 → 实施关键动作 → 产生特定结果/影响。\n\n回到第 2 段，我们比对题干与原文定位句的对应关系，明确本题的论证重心与事实依托。",
          "html": "<h2>32题</h2>\n<p><strong>Those who are against gene patents believe that _____.</strong></p>\n<blockquote><p>那些反对基因专利的人认为_____。</p></blockquote>\n<p>我们先看题干中的核心考查点。根据题文同序原则与刚才粗读文章的逻辑脉络，该题干讨论的内容主要在第 <strong>2</strong> 段展开，所以我们直接回第 <strong>2</strong> 段定位精读。</p>\n<blockquote>\n<p><strong>原文参考：</strong></p>\n<p>On July 29th they were relieved, at least temporarily. A federal appeals court overturned the prior decision, ruling that Myriad Genetics could indeed hold patents to two genes that help forecast a woman’s risk of breast cancer. The chief executive of Myriad, a company in Utah, said the ruling was a blessing to firms and patients alike.</p>\n<p><strong>开始精读：</strong></p>\n<p>On July 29th they were relieved, / at least temporarily. / A federal appeals court overturned the prior decision, / ruling / that Myriad Genetics could indeed hold patents to two genes / that help forecast a woman’s risk of breast cancer. / The chief executive of Myriad, / a company in Utah, / said the ruling was a blessing to firms and patients alike.</p>\n<p><strong>逐意群顺译：</strong></p>\n<p>7 月 29 日，他们松了一口气，至少暂时松了口气。联邦上诉法院推翻了先前的裁决，裁定 Myriad Genetics 确实可以拥有两个有助于预测女性患乳腺癌风险的基因的专利。犹他州 Myriad 公司的首席执行官表示，这一裁决对公司和患者来说都是一件好事。</p>\n<p><strong>意群逻辑串联：</strong></p>\n<p>核心主体 → 实施关键动作 → 产生特定结果/影响。</p>\n</blockquote>\n<p>回到第 2 段，我们比对题干与原文定位句的对应关系，明确本题的论证重心与事实依托。</p>",
