          "html": "<section class=\"revealPart\" id=\"focus-paragraph-1-0\">\n<h3>完整原文 · 第1段</h3>\n<p>In 2010, a federal judge shook America’s biotech industry to its core. Companies had won patents for isolated DNA for decades—by 2005 some 20 % of human genes were parented. But in March 2010 a judge ruled that genes were unpatentable. Executives were violently agitated. The Biotechnology Industry Organisation (BIO), a trade group, assured members that this was just a “preliminary step” in a longer battle.</p>\n</section>\n<section class=\"revealPart\" id=\"focus-paragraph-1-1\">\n<h3>意群划分 · 第1段</h3>\n<p>In 2010, / a federal judge shook America’s biotech industry to its core. / Companies had won patents for isolated DNA for decades—by 2005 some 20 % of human genes were parented. / But in March 2010 a judge ruled / that genes were unpatentable. / Executives were violently agitated. / The Biotechnology Industry Organisation (BIO), / a trade group, / assured members / that this was just a “preliminary step” in a longer battle.</p>\n</section>\n<section class=\"revealPart\" id=\"focus-paragraph-1-2\">\n<h3>意群翻译 · 第1段</h3>\n<p style=\"line-height:1.8;color:#2563eb;font-weight:500\">2010年 / 一位联邦法官彻底震撼了美国生物技术产业<br>数十年来，各家公司都获得了分离 DNA 的专利——到 2005 年，大约 20% 的人类基因是由父母亲授的<br>但 2010 年 3 月，法官做出裁决 / 基因无法申请专利<br>高管们情绪激动<br>生物技术产业组织 (BIO) / 一个贸易集团 / 放心会员 / 这只是一场长期战斗中的“第一步”</p>\n</section>\n<section class=\"revealPart\" id=\"focus-paragraph-1-3\">\n<h3>标准译文 · 第1段</h3>\n<p>2010 年，一位联邦法官彻底震撼了美国生物技术产业。几十年来，公司已经获得了分离 DNA 的专利——到 2005 年，大约 20% 的人类基因是有亲本的。但 2010 年 3 月，一位法官裁定基因不可申请专利。高管们非常激动。贸易组织生物技术工业组织（BIO）向成员保证，这只是一场长期斗争中的“初步步骤”。</p>\n</section>",
