          "section": 2,
          "title": "第2段 · 篇章精读",
          "html": "<section class=\"revealPart\" id=\"focus-paragraph-2-0\">\n<h3>完整原文 · 第2段</h3>\n<p>On July 29th they were relieved, at least temporarily. A federal appeals court overturned the prior decision, ruling that Myriad Genetics could indeed hold patents to two genes that help forecast a woman’s risk of breast cancer. The chief executive of Myriad, a company in Utah, said the ruling was a blessing to firms and patients alike.</p>\n</section>\n<section class=\"revealPart\" id=\"focus-paragraph-2-1\">\n<h3>意群划分 · 第2段</h3>\n<p>On July 29th they were relieved, / at least temporarily. / A federal appeals court overturned the prior decision, / ruling / that Myriad Genetics could indeed hold patents to two genes / that help forecast a woman’s risk of breast cancer. / The chief executive of Myriad, / a company in Utah, / said the ruling was a blessing to firms and patients alike.</p>\n</section>\n<section class=\"revealPart\" id=\"focus-paragraph-2-2\">\n<h3>意群翻译 · 第2段</h3>\n<p style=\"line-height:1.8;color:#2563eb;font-weight:500\">7月29日，他们松了一口气 / 至少暂时<br>联邦上诉法院推翻了先前的裁决 / 裁决 / Myriad Genetics 确实可以拥有两个基因的专利 / 有助于预测女性患乳腺癌的风险<br>Myriad 首席执行官 / 犹他州的一家公司 / 表示这一裁决对公司和患者来说都是福音</p>\n</section>",
          "meta": {
            "section": 2,
            "para": 1,
            "form": 2
          }
