          "html": "<section class=\"revealPart\" id=\"focus-paragraph-3-0\">\n<h3>完整原文 · 第3段</h3>\n<p>But as companies continue their attempts at personalised medicine, the courts will remain rather busy. The Myriad case itself is probably not over. Critics make three main arguments against gene patents: a gene is a product of nature, so it may not be patented; gene patents suppress innovation rather than reward it; and patents’ monopolies restrict access to genetic tests such as Myriad’s. A growing number seem to agree. Last year a federal task-force urged reform for patents related to genetic tests. In October the Department of Justice filed a brief in the Myriad case, arguing that an isolated DNA molecule “is no less a product of nature ... than are cotton fibres that have been separated from cotton seeds.”</p>\n</section>\n<section class=\"revealPart\" id=\"focus-paragraph-3-1\">\n<h3>意群划分 · 第3段</h3>\n<p>But as companies continue their attempts at personalised medicine, / the courts will remain rather busy. / The Myriad case itself is probably not over. / Critics make three main arguments against gene patents: / a gene is a product of nature, / so it may not be patented; / gene patents suppress innovation / rather than reward it; / and patents’ monopolies restrict access to genetic tests such as Myriad’s. / A growing number seem to agree. / Last year a federal task-force urged reform for patents related to genetic tests. / In October the Department of Justice filed a brief in the Myriad case, / arguing / that an isolated DNA molecule “is no less a product of nature ... than are cotton fibres / that have been separated from cotton seeds.”</p>\n</section>\n<section class=\"revealPart\" id=\"focus-paragraph-3-2\">\n<h3>意群翻译 · 第3段</h3>\n<p style=\"line-height:1.8;color:#2563eb;font-weight:500\">但随着公司继续尝试个性化医疗 / 法院仍将相当忙碌<br>Myriad 案本身可能还没有结束<br>批评者提出反对基因专利的三个主要论点 / 基因是自然的产物 / 所以它可能不会获得专利 / 基因专利压制创新 / 而不是奖励它 / 专利垄断限制了 Myriad 等基因测试的使用<br>越来越多的人似乎同意<br>去年，一个联邦工作组敦促对与基因测试相关的专利进行改革<br>10 月，司法部就 Myriad 案提交了一份简报 / 争论 / 一个分离的 DNA 分子“不亚于自然的产物<br>比棉纤维 / 是从棉花种子中分离出来的。”</p>\n</section>\n<section class=\"revealPart\" id=\"focus-paragraph-3-3\">\n<h3>标准译文 · 第3段</h3>\n<p>但随着公司继续尝试个性化医疗，法院将仍然相当忙碌。 Myriad 案本身可能还没有结束。批评者对基因专利提出了三个主要论点：基因是自然的产物，因此不能申请专利；基因专利抑制创新而不是奖励创新；专利垄断限制了 Myriad 等基因检测的使用。越来越多的人似乎同意这一观点。去年，一个联邦工作组敦促对与基因测试相关的专利进行改革。 10 月，司法部就 Myriad 案提交了一份简报，称分离出的 DNA 分子“与从棉籽中分离出来的棉花纤维一样，都是自然产物……”。</p>\n</section>",
