          "html": "<section class=\"revealPart\" id=\"focus-paragraph-6-0\">\n<h3>完整原文 · 第6段</h3>\n<p>Companies are unlikely to file many more patents for human DNA molecules—most are already patented or in the public domain. Firms are now studying how genes interact, looking for correlations that might be used to determine the causes of disease or predict a drug’s efficacy. Companies are eager to win patents for “connecting the dots”, explains Hans Sauer, a lawyer for the BIO.</p>\n</section>\n<section class=\"revealPart\" id=\"focus-paragraph-6-1\">\n<h3>意群划分 · 第6段</h3>\n<p>Companies are unlikely to file many more patents for human DNA molecules—most are already patented or in the public domain. / Firms are now studying how genes interact, / looking for correlations / that might be used to determine the causes of disease or predict a drug’s efficacy. / Companies are eager to win patents for “connecting the dots”, / explains Hans Sauer, / a lawyer for the BIO.</p>\n</section>\n<section class=\"revealPart\" id=\"focus-paragraph-6-2\">\n<h3>意群翻译 · 第6段</h3>\n<p style=\"line-height:1.8;color:#2563eb;font-weight:500\">公司不太可能为人类 DNA 分子申请更多专利——大多数已经获得专利或属于公共领域<br>公司现在正在研究基因如何相互作用 / 寻找相关性 / 可用于确定疾病原因或预测药物疗效<br>Companies are eager to win patents for “connecting the dots / 汉斯·绍尔解释说 / BIO 的律师</p>\n</section>\n<section class=\"revealPart\" id=\"focus-paragraph-6-3\">\n<h3>标准译文 · 第6段</h3>\n<p>公司不太可能为人类 DNA 分子申请更多专利——大多数已经获得专利或属于公共领域。公司现在正在研究基因如何相互作用，寻找可用于确定疾病原因或预测药物疗效的相关性。 BIO 律师汉斯·索尔 (Hans Sauer) 解释说，公司渴望赢得“连接点”的专利。</p>\n</section>",
