          "html": "<section class=\"revealPart\" id=\"focus-paragraph-7-0\">\n<h3>完整原文 · 第7段</h3>\n<p>Their success may be determined by a suit related to this issue, brought by the Mayo Clinic, which the Supreme Court will hear in its next term. The BIO recently held a convention which included sessions to coach lawyers on the shifting landscape for patents. Each meeting was packed.</p>\n</section>\n<section class=\"revealPart\" id=\"focus-paragraph-7-1\">\n<h3>意群划分 · 第7段</h3>\n<p>Their success may be determined by a suit related to this issue, / brought by the Mayo Clinic, / / which the Supreme Court will hear in its next term. / The BIO recently held a convention / which included sessions to coach lawyers on the shifting landscape for patents. / Each meeting was packed.</p>\n</section>\n<section class=\"revealPart\" id=\"focus-paragraph-7-2\">\n<h3>意群翻译 · 第7段</h3>\n<p style=\"line-height:1.8;color:#2563eb;font-weight:500\">他们的成功可能取决于与此问题相关的诉讼 / 由梅奥诊所带来 / 最高法院将在下一届任期内审理<br>BIO最近召开了一次大会 / 其中包括指导律师了解不断变化的专利格局的课程<br>每次会议都座无虚席</p>\n</section>",
