          "section": "先读题干",
          "raw": "## 36题题干\n\n**By saying “to find silver linings” (Paragraph 2) the author suggests that the jobless try to \n_____.**\n\n> By saying “to find silver linings” (Paragraph 2) the author suggests that the jobless try to \n_____.\n\n题型：**事实细节题**。\n\n定位预判：**Paragraph 1**\n\n---",
