          "html": "<div class=\"coarseStack\"><div class=\"coarsePara coarseDone\"><p>1、【段落1大意】围绕本段核心句，阐明论点与主要论据支撑。</p></div><div class=\"coarsePara currentFocus\"><p>【第2段意群顺译】在它结束之前，它很可能会改变一代年轻人的生命历程和性格。最终，它可能会在未来几年重塑我们的政治、文化和社会特征。...</p></div></div>",
