          "html": "<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n  <th>表达</th><th>词性＋意思</th>\n  <th>表达</th><th>词性＋意思</th>\n  <th>表达</th><th>词性＋意思</th>\n</tr>\n</thead>\n<tbody><tr><td><strong>period</strong></td><td>n. 一段时间，时期；阶段，时代；纪</td><td><strong>weakness</strong></td><td>n. 虚弱，软弱；缺点，不足；疲软</td><td><strong>reinforce</strong></td><td>v. 加强，强化；加固，使更结实；给……加强力量，增援</td></tr><tr><td><strong>class</strong></td><td>n. 班级；课，上课时间；课程</td><td><strong>divides</strong></td><td>v. 动词 divide 的第三人称单数形式：分开，划分，分割；分岔；分配，分摊</td><td><strong>opportunities</strong></td><td>n. 因素；机会；机遇</td></tr><tr><td><strong>cross</strong></td><td>v. 反对；杂交；在上划线</td><td><strong>especially</strong></td><td>adv. 尤其，特别；专门，特地；在很大程度上，非常</td><td><strong>young</strong></td><td>adj. 幼小的，年轻的；存在不久的，新成立的；年轻的，岁数不大的</td></tr></tbody>\n</table></div>",
