          "html": "<section class=\"revealPart\" id=\"focus-paragraph-3-0\">\n<h3>完整原文 · 第3段</h3>\n<p>No one tries harder than the jobless to find silver linings in this national economic disaster. Many said that unemployment, while extremely painful, had improved them in some ways; they had become less materialistic and more financially prudent; they were more aware of the struggles of others. In limited respects, perhaps the recession will leave society better off. At the very least, it has awoken us from our national fever dream of easy riches and bigger houses, and put a necessary end to an era of reckless personal spending.</p>\n</section>\n<section class=\"revealPart\" id=\"focus-paragraph-3-1\">\n<h3>意群划分 · 第3段</h3>\n<p>No one tries harder than the jobless to find silver linings in this national economic disaster. / Many said / that unemployment, / / while extremely painful, / had improved them in some ways; / they had become less materialistic and more financially prudent; / they were more aware of the struggles of others. / In limited respects, / perhaps the recession will leave society better off. / At the very least, / it has awoken us from our national fever dream of easy riches and bigger houses, / and put a necessary end to an era of reckless personal spending.</p>\n</section>",
