          "html": "<section class=\"revealPart\" id=\"focus-paragraph-4-0\">\n<h3>完整原文 · 第4段</h3>\n<p>But for the most part, these benefits seem thin, uncertain, and far off. In The Moral Consequences of Economic Growth, the economic historian Benjamin Friedman argues that both inside and outside the U.S., lengthy periods of economic stagnation or decline have almost always left society more mean-spirited and less inclusive, and have usually stopped or reversed the advance of rights and freedoms. Anti-immigrant sentiment typically increases, as does conflict between races and classes.</p>\n</section>\n<section class=\"revealPart\" id=\"focus-paragraph-4-1\">\n<h3>意群划分 · 第4段</h3>\n<p>But for the most part, / these benefits seem thin, / uncertain, / and far off. / In The Moral Consequences of Economic Growth, / the economic historian Benjamin Friedman argues / that both inside and outside the U.S., / lengthy periods of economic stagnation or decline have almost always left society more mean-spirited and less inclusive, / and have usually stopped or reversed the advance of rights and freedoms. / Anti-immigrant sentiment typically increases, / as does conflict between races and classes.</p>\n</section>\n<section class=\"revealPart\" id=\"focus-paragraph-4-2\">\n<h3>意群翻译 · 第4段</h3>\n<p style=\"line-height:1.8;color:#2563eb;font-weight:500\">但大多数情况下 / 这些好处似乎很薄弱 / 不确定 / 和遥远的地方<br>经济增长的道德后果 / 经济历史学家本杰明·弗里德曼认为 / 无论是在美国境内还是境外 / 长期的经济停滞或衰退几乎总是让社会变得更加卑鄙和包容 / 通常会阻止或逆转权利和自由的进步<br>反移民情绪通常会增加 / 种族和阶级之间的冲突也是如此</p>\n</section>",
