          "html": "<section class=\"revealPart\" id=\"focus-paragraph-5-0\">\n<h3>完整原文 · 第5段</h3>\n<p>Income inequality usually falls during a recession, but it has not shrunk in this one.</p>\n</section>\n<section class=\"revealPart\" id=\"focus-paragraph-5-1\">\n<h3>意群划分 · 第5段</h3>\n<p>Income inequality usually falls during a recession, / but it has not shrunk in this one.</p>\n</section>\n<section class=\"revealPart\" id=\"focus-paragraph-5-2\">\n<h3>意群翻译 · 第5段</h3>\n<p style=\"line-height:1.8;color:#2563eb;font-weight:500\">经济衰退期间收入不平等通常会下降 / 但它并没有在这一个中缩水</p>\n</section>\n<section class=\"revealPart\" id=\"focus-paragraph-5-3\">\n<h3>标准译文 · 第5段</h3>\n<p>收入不平等通常会在经济衰退期间缩小，但在这次衰退中并没有缩小。</p>\n</section>",
