          "html": "<section class=\"revealPart\" id=\"focus-paragraph-6-0\">\n<h3>完整原文 · 第6段</h3>\n<p>Indeed, this period of economic weakness may reinforce class divides, and decrease opportunities to cross them—especially for young people. The research of Till V on Wachter, the economist at Columbia University, suggests that not all people graduating into a recession see their life chances dimmed: those with degrees from elite universities catch up fairly quickly to where they otherwise would have been if they had graduated in better times; it is the masses beneath them that are left behind.</p>\n</section>\n<section class=\"revealPart\" id=\"focus-paragraph-6-1\">\n<h3>意群划分 · 第6段</h3>\n<p>Indeed, / this period of economic weakness may reinforce class divides, / and decrease opportunities to cross them—especially for young people. / The research of Till V on Wachter, / the economist at Columbia University, / suggests / that not all people graduating into a recession see their life chances dimmed: / those with degrees from elite universities catch up fairly quickly to / where they otherwise would have been / if they had graduated in better times; / it is the masses beneath them / that are left behind.</p>\n</section>\n<section class=\"revealPart\" id=\"focus-paragraph-6-2\">\n<h3>意群翻译 · 第6段</h3>\n<p style=\"line-height:1.8;color:#2563eb;font-weight:500\">的确 / 这段经济疲软时期可能会加剧阶级分化 / 并减少穿越它们的机会——尤其是年轻人<br>Till V 对 Wachter 的研究 / 哥伦比亚大学经济学家 / 建议 / 并非所有进入经济衰退的人都会看到他们的生活机会变得黯淡 / 那些拥有精英大学学位的人很快就能赶上 / 否则他们会在哪里 / 如果他们毕业的时候比较好的话 / 这是他们下面的群众 / 被留下的</p>\n</section>",
