          "html": "<section class=\"revealPart\" id=\"focus-paragraph-7-0\">\n<h3>完整原文 · 第7段</h3>\n<p>In the Internet age, it is particularly easy to see the resentment that has always been hidden within American society. More difficult, in the moment, is discerning precisely how these lean times are affecting society’s character. In many respects, the U.S. was more socially tolerant entering this recession than at any time in its history, and a variety of national polls on social conflict since then have shown mixed results. We will have to wait and see exactly how these hard times will reshape our social fabric. But they certainly will reshape it, and all the more so the longer they extend.</p>\n</section>\n<section class=\"revealPart\" id=\"focus-paragraph-7-1\">\n<h3>意群划分 · 第7段</h3>\n<p>In the Internet age, / it is particularly easy to see the resentment / that has always been hidden within American society. / More difficult, / in the moment, / is discerning precisely how these lean times are affecting society’s character. / In many respects, / the U.S. was more socially tolerant entering this recession than at any time in its history, / and a variety of national polls on social conflict / since then have shown mixed results. / We will have to wait and see exactly how these hard times will reshape our social fabric. / But they certainly will reshape it, / and all the more so the longer they extend.</p>\n</section>\n<section class=\"revealPart\" id=\"focus-paragraph-7-2\">\n<h3>意群翻译 · 第7段</h3>\n<p style=\"line-height:1.8;color:#2563eb;font-weight:500\">在网络时代 / 特别容易看出反感 / 一直隐藏在美国社会中<br>比较困难 / 此刻 / 准确地洞察这些困难时期如何影响社会特征<br>在很多方面 / 美国<br>进入这次衰退的社会容忍度比历史上任何时期都高 / 以及各种关于社会冲突的全国民意调查 / 从那时起，结果好坏参半<br>我们将不得不等待，看看这些困难时期将如何重塑我们的社会结构<br>但他们肯定会重塑它 / 而且它们延伸的时间越长</p>\n</section>\n<section class=\"revealPart\" id=\"focus-paragraph-7-3\">\n<h3>标准译文 · 第7段</h3>\n<p>在网络时代，特别容易看到美国社会内部一直隐藏的怨恨情绪。目前，更困难的是准确辨别这些经济不景气的时期如何影响社会特征。在许多方面，美国在进入这次衰退时比历史上任何时候都更加宽容，自那时以来有关社会冲突的各种全国民意调查显示出不同的结果。我们将不得不拭目以待，看看这些困难时期将如何重塑我们的社会结构。但他们肯定会重塑它，而且随着时间的延长，情况更是如此。</p>\n</section>",
